# owner: platform
import unittest

from hourglass.timesheet import timesheet_lines
from hourglass.parsing import parse_span
from hourglass.models import Shift

# ---
def make_shift(worker, date, text):
    return Shift(worker, date, parse_span(text))

class TimesheetTests(unittest.TestCase):
    def test_busiest_first(self):
        shifts = [
            make_shift("Brisa", "mon", "09:00-10:00"),
            make_shift("Corin", "mon", "09:00-17:30"),
            make_shift("Brisa", "tue", "09:00-10:30")
        ]
        self.assertEqual(
            timesheet_lines(shifts),
            [
                "Corin: 1 shifts, 8.5 hours",
                "Brisa: 2 shifts, 2.5 hours"
            ]
        )

    def test_ties_break_by_name(self):
        shifts = [
            make_shift("Zane", "mon", "09:00-10:00"),
            make_shift("Anya", "mon", "09:00-10:00")
        ]
        lines = timesheet_lines(shifts)
        self.assertTrue(lines[0].startswith("Anya"))

    def test_rounds_to_one_decimal(self):
        shifts = [make_shift("Brisa", "mon", "09:00-09:20")]
        self.assertEqual(
            timesheet_lines(shifts),
            ["Brisa: 1 shifts, 0.3 hours"]
        )

    def test_empty_list(self):
        with self.assertRaises(ValueError):
            timesheet_lines([])

    def test_blank_worker(self):
        shifts = [make_shift("  ", "mon", "09:00-10:00")]
        with self.assertRaises(ValueError):
            timesheet_lines(shifts)
